import 'dart:async';

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_bloc.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
import 'package:cerne/features/capture/presentation/widgets/audio_tab_view.dart';
import 'package:cerne/features/capture/presentation/widgets/capture_tab_bar.dart';
import 'package:cerne/features/capture/presentation/widgets/foto_tab_view.dart';
import 'package:cerne/features/capture/presentation/widgets/texto_tab_view.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

/// Shown via `showModalBottomSheet` as an overlay above Home/Chat (with a
/// darkened scrim) without discarding or navigating away from Home/Chat's
/// state underneath (FR-001) — `showModalBottomSheet` gives the scrim and
/// overlay semantics for free. An exhaustive `BlocBuilder` switch over
/// [InsertionModalState] drives the three tab bodies, plus a listener on
/// the bloc's one-shot [InsertionModalBloc.closeRequests] that pops the
/// sheet on a successful save (FR-011).
class InsertionModalPage extends StatefulWidget {
  const InsertionModalPage({super.key});

  @override
  State<InsertionModalPage> createState() => _InsertionModalPageState();
}

class _InsertionModalPageState extends State<InsertionModalPage> {
  late final StreamSubscription<void> _closeSubscription;

  @override
  void initState() {
    super.initState();
    _closeSubscription = context
        .read<InsertionModalBloc>()
        .closeRequests
        .listen((_) {
          if (mounted && Navigator.of(context).canPop()) {
            Navigator.of(context).pop();
          }
        });
  }

  @override
  void dispose() {
    _closeSubscription.cancel();
    super.dispose();
  }

  CaptureTab _tabOf(InsertionModalState state) => switch (state) {
    InsertionModalTexto() ||
    InsertionModalTextoSaving() ||
    InsertionModalTextoFailure() => CaptureTab.texto,
    InsertionModalAudioIdle() ||
    InsertionModalAudioPermissionDenied() ||
    InsertionModalAudioRecording() ||
    InsertionModalAudioSaving() ||
    InsertionModalAudioFailure() => CaptureTab.audio,
    InsertionModalFotoCaptura() ||
    InsertionModalFotoPermissionDenied() ||
    InsertionModalFotoSaving() ||
    InsertionModalFotoFailure() => CaptureTab.foto,
  };

  @override
  Widget build(BuildContext context) {
    return AnimatedPadding(
      duration: const Duration(milliseconds: 100),
      padding: EdgeInsets.only(
        bottom: MediaQuery.of(context).viewInsets.bottom,
      ),
      child: SafeArea(
        child: SingleChildScrollView(
          padding: const EdgeInsets.all(DesignTokens.spacingMd),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Row(
                children: [
                  Expanded(
                    child: Text(
                      'Nova entrada',
                      style: DesignTokens.textTitleLg,
                    ),
                  ),
                  IconButton(
                    onPressed: () {
                      context.read<InsertionModalBloc>().add(
                        const ModalClosed(),
                      );
                      Navigator.of(context).pop();
                    },
                    icon: const Icon(Icons.close),
                  ),
                ],
              ),
              const SizedBox(height: DesignTokens.spacingMd),
              BlocBuilder<InsertionModalBloc, InsertionModalState>(
                builder: (context, state) {
                  return Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      CaptureTabBar(
                        activeTab: _tabOf(state),
                        onTabSelected: (tab) => context
                            .read<InsertionModalBloc>()
                            .add(TabSelected(tab)),
                      ),
                      const SizedBox(height: DesignTokens.spacingMd),
                      switch (state) {
                        InsertionModalTexto() ||
                        InsertionModalTextoSaving() ||
                        InsertionModalTextoFailure() => TextoTabView(
                          state: state,
                        ),
                        InsertionModalAudioIdle() ||
                        InsertionModalAudioPermissionDenied() ||
                        InsertionModalAudioRecording() ||
                        InsertionModalAudioSaving() ||
                        InsertionModalAudioFailure() => AudioTabView(
                          state: state,
                        ),
                        InsertionModalFotoCaptura() ||
                        InsertionModalFotoPermissionDenied() ||
                        InsertionModalFotoSaving() ||
                        InsertionModalFotoFailure() => FotoTabView(
                          state: state,
                        ),
                      },
                    ],
                  );
                },
              ),
            ],
          ),
        ),
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
import 'package:flutter/material.dart';

/// Exactly three capture modes as tabs, with the active tab visually
/// distinguished (FR-002).
class CaptureTabBar extends StatelessWidget {
  const CaptureTabBar({
    required this.activeTab,
    required this.onTabSelected,
    super.key,
  });

  final CaptureTab activeTab;
  final ValueChanged<CaptureTab> onTabSelected;

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        Expanded(
          child: _TabButton(
            label: 'Texto',
            tab: CaptureTab.texto,
            activeTab: activeTab,
            onTabSelected: onTabSelected,
          ),
        ),
        const SizedBox(width: DesignTokens.spacingSm),
        Expanded(
          child: _TabButton(
            label: 'Áudio',
            tab: CaptureTab.audio,
            activeTab: activeTab,
            onTabSelected: onTabSelected,
          ),
        ),
        const SizedBox(width: DesignTokens.spacingSm),
        Expanded(
          child: _TabButton(
            label: 'Foto',
            tab: CaptureTab.foto,
            activeTab: activeTab,
            onTabSelected: onTabSelected,
          ),
        ),
      ],
    );
  }
}

class _TabButton extends StatelessWidget {
  const _TabButton({
    required this.label,
    required this.tab,
    required this.activeTab,
    required this.onTabSelected,
  });

  final String label;
  final CaptureTab tab;
  final CaptureTab activeTab;
  final ValueChanged<CaptureTab> onTabSelected;

  @override
  Widget build(BuildContext context) {
    final isActive = tab == activeTab;
    return GestureDetector(
      onTap: () => onTabSelected(tab),
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: DesignTokens.spacingSm),
        decoration: BoxDecoration(
          color: isActive
              ? DesignTokens.colorPrimary
              : DesignTokens.colorSurfaceElevated,
          borderRadius: BorderRadius.circular(DesignTokens.radiusMd),
          border: Border.all(color: DesignTokens.colorBorder),
        ),
        alignment: Alignment.center,
        child: Text(
          label,
          style: DesignTokens.textLabelMd.copyWith(
            color: isActive
                ? DesignTokens.colorOnPrimary
                : DesignTokens.colorTextPrimary,
          ),
        ),
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_bloc.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
import 'package:cerne/features/capture/presentation/widgets/capture_status_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

/// A free multiline text field and a "Salvar" action unavailable while the
/// field is empty (FR-003). Renders the plain generic loading indicator
/// while saving and a plain failure message on failure (FR-007/FR-009) —
/// tapping "Salvar" again is the retry, no dedicated retry affordance
/// needed for this tab.
class TextoTabView extends StatelessWidget {
  const TextoTabView({required this.state, super.key});

  final InsertionModalState state;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<InsertionModalBloc>();
    final text = switch (state) {
      InsertionModalTexto(text: final t) => t,
      InsertionModalTextoSaving(text: final t) => t,
      InsertionModalTextoFailure(text: final t) => t,
      _ => '',
    };
    final isSaving = state is InsertionModalTextoSaving;
    final failure = state;
    final failureMessage = failure is InsertionModalTextoFailure
        ? failure.message
        : null;

    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          TextFormField(
            key: const ValueKey('textoTabField'),
            initialValue: text,
            enabled: !isSaving,
            maxLines: 6,
            minLines: 3,
            decoration: const InputDecoration(
              hintText: 'Escreva sua entrada...',
            ),
            onChanged: (value) => bloc.add(TextDraftChanged(value)),
          ),
          if (failureMessage != null) ...[
            const SizedBox(height: DesignTokens.spacingSm),
            Text(
              failureMessage,
              style: DesignTokens.textBodyMd.copyWith(
                color: DesignTokens.colorError,
              ),
            ),
          ],
          const SizedBox(height: DesignTokens.spacingLg),
          if (isSaving)
            const CaptureLoadingIndicator()
          else
            ElevatedButton(
              onPressed: text.trim().isNotEmpty
                  ? () => bloc.add(const SaveTextSubmitted())
                  : null,
              child: const Text('Salvar'),
            ),
        ],
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_bloc.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
import 'package:cerne/features/capture/presentation/widgets/audio_waveform.dart';
import 'package:cerne/features/capture/presentation/widgets/capture_status_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

const _permissionDeniedMessage =
    'Permita o acesso ao microfone para gravar um áudio.';

/// A round start control with the "Toque para gravar" caption for
/// [InsertionModalAudioIdle] (FR-004); a stop control, [AudioWaveform], and
/// a running `mm:ss` timer for [InsertionModalAudioRecording]; the
/// permission-denied message; the plain generic loading indicator for
/// [InsertionModalAudioSaving] (FR-007); a plain failure message plus one
/// generic retry action for [InsertionModalAudioFailure], deliberately not
/// reproducing the prototype's named "Áudio — Erro" styling/copy
/// (research.md R11).
class AudioTabView extends StatelessWidget {
  const AudioTabView({required this.state, super.key});

  final InsertionModalState state;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<InsertionModalBloc>();
    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      child: switch (state) {
        InsertionModalAudioIdle() => _IdleView(
          onStart: () => bloc.add(const AudioStartRequested()),
        ),
        InsertionModalAudioPermissionDenied() =>
          const CapturePermissionDeniedMessage(
            message: _permissionDeniedMessage,
          ),
        InsertionModalAudioRecording(elapsed: final elapsed) => _RecordingView(
          elapsed: elapsed,
          onStop: () => bloc.add(const AudioStopRequested()),
        ),
        InsertionModalAudioSaving() => const CaptureLoadingIndicator(),
        InsertionModalAudioFailure(message: final message) =>
          CaptureFailureBand(
            message: message,
            onRetry: () => bloc.add(const RetryRequested()),
          ),
        _ => const SizedBox.shrink(),
      },
    );
  }
}

class _IdleView extends StatelessWidget {
  const _IdleView({required this.onStart});

  final VoidCallback onStart;

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        GestureDetector(
          onTap: onStart,
          child: Container(
            width: DesignTokens.sizeBiometricIconContainer,
            height: DesignTokens.sizeBiometricIconContainer,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: DesignTokens.colorSurfaceElevated,
              border: Border.all(
                color: DesignTokens.colorBorder,
                width: DesignTokens.borderWidthFocused,
              ),
              boxShadow: DesignTokens.elevation1,
            ),
            child: const Icon(
              Icons.mic,
              size: DesignTokens.sizeBiometricIcon,
              color: DesignTokens.colorPrimary,
            ),
          ),
        ),
        const SizedBox(height: DesignTokens.spacingLg),
        Text('Toque para gravar', style: DesignTokens.textTitleLg),
      ],
    );
  }
}

class _RecordingView extends StatelessWidget {
  const _RecordingView({required this.elapsed, required this.onStop});

  final Duration elapsed;
  final VoidCallback onStop;

  @override
  Widget build(BuildContext context) {
    final minutes = elapsed.inMinutes.toString().padLeft(2, '0');
    final seconds = (elapsed.inSeconds % 60).toString().padLeft(2, '0');

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        const AudioWaveform(),
        const SizedBox(height: DesignTokens.spacingMd),
        Text('$minutes:$seconds', style: DesignTokens.textMonoCaption),
        const SizedBox(height: DesignTokens.spacingLg),
        IconButton(
          onPressed: onStop,
          icon: const Icon(Icons.stop_circle, color: DesignTokens.colorError),
          iconSize: DesignTokens.spacing2xl,
        ),
      ],
    );
  }
}

